extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var lantern := main.get_node_or_null("Lantern") as Node3D
	if check("lantern_exists", lantern != null, "In main.tscn serve il nodo Lantern"):
		check("scale", lantern.scale.distance_to(Vector3(1, 1, 1)) < 0.05, "La scala di Lantern deve essere (1, 1, 1) (è %s)" % str(lantern.scale))
		check("rot_y", absf(lantern.rotation_degrees.y) < 0.1, "La rotazione Y di Lantern deve essere 0 (è %.1f)" % lantern.rotation_degrees.y)
	var lantern_scene := await instantiate_scene("res://lantern.tscn")
	if check("scene_exists", lantern_scene != null, "La scena lantern.tscn deve caricarsi correttamente"):
		var col := lantern_scene.find_child("CollisionShape3D", true, false) as CollisionShape3D
		check("has_col", col != null and col.shape is CylinderShape3D, "lantern.tscn deve contenere una CollisionShape3D con forma CylinderShape3D")
